static int mtTextW(const char *s)
{
  int w = 0;
  for (; *s; s++)
    if (*s >= 32 && *s < 127)
      w += MT_GLYPHS[*s - 32].adv;
  return (int)(w * UI_TS + 0.5f);
}

static void mtPrint(int x, int y, const char *s, uint16_t col)
{
  for (; *s; s++)
  {
    if (*s < 32 || *s >= 127)
      continue;
    const MTGlyph &g = MT_GLYPHS[*s - 32];
    int stride = (g.w + 7) / 8;
    for (int gy = 0; gy < MT_H; gy++)
    {
      int y0 = y + (int)(gy * UI_TS);
      int y1 = y + (int)((gy + 1) * UI_TS);
      if (y1 <= y0)
        y1 = y0 + 1;
      int run = -1;
      for (int gx = 0; gx <= g.w; gx++)
      {
        bool lit = gx < g.w &&
                   (MT_BITS[g.off + gy * stride + gx / 8] & (0x80 >> (gx & 7)));
        if (lit && run < 0)
          run = gx;
        else if (!lit && run >= 0)
        {
          int rx = x + (int)((g.xoff + run) * UI_TS);
          int rx1 = x + (int)((g.xoff + gx) * UI_TS);
          canvas->fillRect(rx, y0, rx1 - rx, y1 - y0, col);
          run = -1;
        }
      }
    }
    x += (int)(g.adv * UI_TS);
  }
}
